SELECT s.name AS SchemaName,t.name AS TableName,c.name AS ColumnName,ty.name AS DataType FROM sys.tables t JOIN sys.schemas s ON t.schema_id=s.schema_id JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON c.user_type_id=ty.user_type_id WHERE t.name IN ('WorkOrder','BillOfMaterials','ProductVendor','TransactionHistory','TransactionHistoryArchive','Product','UnitMeasure') ORDER BY s.name,t.name,c.column_id;
SELECT 'WorkOrder' AS Source,COUNT(*) AS Rows,MIN(StartDate) AS MinDate,MAX(StartDate) AS MaxDate FROM Production.WorkOrder;
SELECT 'Current' AS Source,TransactionType,COUNT(*) AS Rows,COUNT(DISTINCT ProductID) AS Products,MIN(TransactionDate) AS MinDate,MAX(TransactionDate) AS MaxDate,MIN(Quantity) AS MinQty,MAX(Quantity) AS MaxQty FROM Production.TransactionHistory GROUP BY TransactionType UNION ALL SELECT 'Archive',TransactionType,COUNT(*),COUNT(DISTINCT ProductID),MIN(TransactionDate),MAX(TransactionDate),MIN(Quantity),MAX(Quantity) FROM Production.TransactionHistoryArchive GROUP BY TransactionType;
